import { useCallback, useMemo, useState } from 'react';
import { Button, ButtonGroup, Calendar, Card, Stack, Text } from '@jinx-ui/react';

// Предполагаемый контракт Calendar из @jinx-ui/react:
// value/onChange для выбранной даты и month/onMonthChange для видимого месяца.
type ReportDatePickerProps = {
  value?: Date;
  defaultValue?: Date;
  onChange: (date: Date) => void;
};

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function addDays(date: Date, days: number): Date {
  const result = startOfDay(date);
  result.setDate(result.getDate() + days);
  return result;
}

function isSameDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function startOfMonth(date: Date): Date {
  const result = startOfDay(date);
  result.setDate(1);
  return result;
}

export default function ReportDatePicker({ value, defaultValue, onChange }: ReportDatePickerProps) {
  const [internalDate, setInternalDate] = useState<Date>(() =>
    startOfDay(defaultValue ?? new Date()),
  );
  const selected = value ? startOfDay(value) : internalDate;

  const [visibleMonth, setVisibleMonth] = useState<Date>(() => startOfMonth(selected));

  const presets = useMemo(() => {
    const today = startOfDay(new Date());
    return [
      { id: 'today', label: 'Сегодня', date: today },
      { id: 'yesterday', label: 'Вчера', date: addDays(today, -1) },
      { id: 'week-ago', label: 'Неделя назад', date: addDays(today, -7) },
    ];
  }, []);

  const selectDate = useCallback(
    (next: Date) => {
      const normalized = startOfDay(next);
      setInternalDate(normalized);
      setVisibleMonth(startOfMonth(normalized));
      onChange(normalized);
    },
    [onChange],
  );

  return (
    <Card>
      <Stack direction="vertical" style={{ gap: 'var(--jx-space-3)' }}>
        <Text as="label" variant="caption">
          Дата отчёта
        </Text>

        <ButtonGroup aria-label="Быстрый выбор даты">
          {presets.map((preset) => (
            <Button
              key={preset.id}
              type="button"
              variant={isSameDay(preset.date, selected) ? 'primary' : 'secondary'}
              aria-pressed={isSameDay(preset.date, selected)}
              onClick={() => selectDate(preset.date)}
            >
              {preset.label}
            </Button>
          ))}
        </ButtonGroup>

        <Calendar
          value={selected}
          month={visibleMonth}
          onMonthChange={(month: Date) => setVisibleMonth(startOfMonth(month))}
          onChange={selectDate}
        />
      </Stack>
    </Card>
  );
}

